alter table public.qr_codes add column if not exists purpose text not null default 'checkin', add column if not exists action_type text not null default 'checkin', add column if not exists action_payload jsonb not null default '{}'::jsonb;
create or replace function public.business_create_custom_qr(p_business_id uuid,p_location_id uuid,p_label text,p_purpose text default 'checkin',p_action_type text default 'checkin',p_action_payload jsonb default '{}'::jsonb,p_customization jsonb default '{}'::jsonb) returns public.qr_codes language plpgsql security definer set search_path=public as $$ declare v public.qr_codes; begin if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in ('owner','admin')) and lower(coalesce((select u.email from auth.users u where u.id=auth.uid()),'')) <> 'matthagersr@gmail.com' then raise exception 'Business owner/admin permission required'; end if; if not exists(select 1 from public.locations l where l.id=p_location_id and l.business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; insert into public.qr_codes(location_id,code,label,active,customization,purpose,action_type,action_payload) values(p_location_id,encode(gen_random_bytes(12),'hex'),nullif(trim(p_label),''),true,coalesce(p_customization,'{}'::jsonb),coalesce(nullif(trim(p_purpose),''),'custom'),coalesce(nullif(trim(p_action_type),''),'custom'),coalesce(p_action_payload,'{}'::jsonb)) returning * into v; return v; end; $$;
create or replace function public.business_update_custom_qr(p_business_id uuid,p_qr_id uuid,p_label text,p_purpose text,p_action_type text,p_action_payload jsonb,p_customization jsonb,p_active boolean default true) returns public.qr_codes language plpgsql security definer set search_path=public as $$ declare v public.qr_codes; begin if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in ('owner','admin')) and lower(coalesce((select u.email from auth.users u where u.id=auth.uid()),'')) <> 'matthagersr@gmail.com' then raise exception 'Business owner/admin permission required'; end if; update public.qr_codes q set label=nullif(trim(p_label),''),purpose=coalesce(nullif(trim(p_purpose),''),'custom'),action_type=coalesce(nullif(trim(p_action_type),''),'custom'),action_payload=coalesce(p_action_payload,'{}'::jsonb),customization=coalesce(p_customization,'{}'::jsonb),active=p_active where q.id=p_qr_id and exists(select 1 from public.locations l where l.id=q.location_id and l.business_id=p_business_id) returning q.* into v; if v.id is null then raise exception 'QR code not found'; end if; return v; end; $$;
create or replace function public.business_delete_qr(p_business_id uuid,p_qr_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in ('owner','admin')) and lower(coalesce((select u.email from auth.users u where u.id=auth.uid()),'')) <> 'matthagersr@gmail.com' then raise exception 'Business owner/admin permission required'; end if; delete from public.qr_codes q where q.id=p_qr_id and exists(select 1 from public.locations l where l.id=q.location_id and l.business_id=p_business_id); return found; end; $$;
create or replace function public.business_update_promotion(p_business_id uuid,p_id uuid,p_title text,p_description text,p_discount text,p_active boolean) returns public.promotions language plpgsql security definer set search_path=public as $$ declare v public.promotions; begin if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in ('owner','admin')) and lower(coalesce((select u.email from auth.users u where u.id=auth.uid()),'')) <> 'matthagersr@gmail.com' then raise exception 'Business owner/admin permission required'; end if; update public.promotions p set title=nullif(trim(p_title),''),description=p_description,discount=p_discount,active=p_active where p.id=p_id and p.business_id=p_business_id returning p.* into v; if v.id is null then raise exception 'Promotion not found'; end if; return v; end; $$;
create or replace function public.business_delete_promotion(p_business_id uuid,p_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in ('owner','admin')) and lower(coalesce((select u.email from auth.users u where u.id=auth.uid()),'')) <> 'matthagersr@gmail.com' then raise exception 'Business owner/admin permission required'; end if; delete from public.promotions p where p.id=p_id and p.business_id=p_business_id; return found; end; $$;
